import * as T from './vendor/three.module.js';
export function roundedBoxGeometry(w,h,d){const b=Math.min(w,h,d,.18)*.16,x=w/2-b,y=h/2-b,r=Math.min(x,y,.085),s=new T.Shape();s.moveTo(-x+r,-y);s.lineTo(x-r,-y);s.quadraticCurveTo(x,-y,x,-y+r);s.lineTo(x,y-r);s.quadraticCurveTo(x,y,x-r,y);s.lineTo(-x+r,y);s.quadraticCurveTo(-x,y,-x,y-r);s.lineTo(-x,-y+r);s.quadraticCurveTo(-x,-y,-x+r,-y);const g=new T.ExtrudeGeometry(s,{depth:d-2*b,steps:1,bevelEnabled:true,bevelSize:b,bevelThickness:b,bevelSegments:3,curveSegments:5});g.translate(0,0,-d/2+b);g.computeVertexNormals();return g;}
export function smoothCarBody(rings){
 const upper=new T.CatmullRomCurve3(rings.map(([z,w,b,t])=>new T.Vector3(z,w,t))),lower=new T.CatmullRomCurve3(rings.map(([z,w,b])=>new T.Vector3(z,w,b)));const positions=[],indices=[],samples=32,n=12,stations=[];
 for(let k=0;k<=samples;k++){const u=upper.getPoint(k/samples),v=lower.getPoint(k/samples),z=u.x,w=u.y,b=v.z,t=u.z;stations.push(z);for(const [x,y]of [[-w*.84,b],[-w*.97,b+.035],[-w,b+.11],[-w,t-.07],[-w*.96,t-.025],[-w*.86,t],[w*.86,t],[w*.96,t-.025],[w,t-.07],[w,b+.11],[w*.97,b+.035],[w*.84,b]])positions.push(x,y,z);}
 for(let k=0;k<samples;k++)for(let i=0;i<n;i++){const z=(stations[k]+stations[k+1])/2;if(i===5&&z>-.96&&z<.98)continue;const a=k*n+i,b=k*n+(i+1)%n,c=b+n,d=a+n;indices.push(a,b,c,a,c,d);}for(let i=1;i<n-1;i++)indices.push(0,i+1,i,samples*n,samples*n+i,samples*n+i+1);const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setIndex(indices);g.computeVertexNormals();return g;
}
export function sculptedDashboard(){const s=new T.Shape();s.moveTo(-.82,.98);s.quadraticCurveTo(-.84,1.18,-.61,1.16);s.quadraticCurveTo(0,1.08,.61,1.16);s.quadraticCurveTo(.84,1.18,.82,.98);s.lineTo(-.82,.98);const g=new T.ExtrudeGeometry(s,{depth:.28,bevelEnabled:true,bevelSize:.025,bevelThickness:.025,bevelSegments:3,curveSegments:12});g.translate(0,0,-.88);return g;}
